<!--
 * 流程实例（列表页）
 *
 * @path apps\workflow-web\src\views\instance\index.vue
 * @author ydsz-team
 * @since 1.0.0
-->
<script lang="ts" setup>
/**
 * 流程实例（列表页）
 * <p>消费后端契约 FlowInstanceController（src/api/flowInstance.ts，auto-generated by bash/gen-contract.py）：
 * 我的发起实例列表 instanceMy()（PageResponse 转 { items, total }），
 * 支持终止 terminate、挂起 suspend / 恢复 activate、撤回 recall、轨迹 timeline 抽屉。
 *
 * @author ydsz-team
 * @since 1.0.0
 */
import type { VxeTableGridOptions } from '@ydsz/plugins/vxe-table';
import { Page, useYDSZModal } from '@ydsz/common-ui';
import { ElButton, ElDrawer, ElMessage, ElMessageBox, ElTable, ElTableColumn, ElTag } from 'element-plus';
import { h, ref } from 'vue';
import { useYDSZVxeGrid } from '#/adapter/vxe-table';
import { activate, instanceMy, recall, suspend, terminate, timeline } from '#/api/flowInstance';
import type { FlowInstanceVO, FlowTimelineVO } from '#/api/models';
import InstanceForm from './instance-form.vue';
defineOptions({ name: 'InstanceManagement' });

/** 流程状态标签（兼容字符串/数字取值，未知值按原始值展示） */
function statusTag(flowStatus: string | undefined) {
  const status = (flowStatus ?? '').toUpperCase();
  if (status === 'FINISHED' || status === 'COMPLETED' || status === '1') {
    return h(ElTag, { type: 'success' }, () => '已完成');
  }
  if (status === 'SUSPENDED' || status === 'PAUSED') {
    return h(ElTag, { type: 'warning' }, () => '已挂起');
  }
  if (status === 'TERMINATED' || status === 'CANCELED') {
    return h(ElTag, { type: 'danger' }, () => '已终止');
  }
  if (status === 'RUNNING' || status === 'ACTIVE') {
    return h(ElTag, { type: 'primary' }, () => '运行中');
  }
  return h(ElTag, {}, () => flowStatus ?? '-');
}

const gridOptions: VxeTableGridOptions<FlowInstanceVO> = {
  columns: [
    { type: 'seq', width: 50, title: '序号' },
    { field: 'flowName', title: '流程名称', width: 180 },
    { field: 'flowCode', title: '流程编码', width: 140 },
    { field: 'title', title: '标题', width: 160 },
    { field: 'businessNo', title: '业务单号', width: 140 },
    { field: 'initiatorName', title: '发起人', width: 100 },
    {
      field: 'flowStatus', title: '状态', width: 90,
      slots: { default: ({ row }) => statusTag(row.flowStatus) },
    },
    { field: 'currentNodeName', title: '当前节点', width: 120 },
    { field: 'startAt', title: '开始时间', width: 170 },
    {
      field: 'action', title: '操作', width: 260, fixed: 'right',
      slots: {
        default: ({ row }) =>
          h('div', { class: 'flex gap-1' }, [
            h(ElButton, { size: 'small', link: true, type: 'danger', onClick: () => handleTerminate(row) }, () => '终止'),
            h(ElButton, { size: 'small', link: true, type: 'warning', onClick: () => handleSuspend(row) }, () => '挂起'),
            h(ElButton, { size: 'small', link: true, type: 'success', onClick: () => handleActivate(row) }, () => '恢复'),
            h(ElButton, { size: 'small', link: true, type: 'primary', onClick: () => handleRecall(row) }, () => '撤回'),
            h(ElButton, { size: 'small', link: true, type: 'primary', onClick: () => openTimeline(row) }, () => '轨迹'),
          ]),
      },
    },
  ],
  height: 'auto',
  pagerConfig: { pageSize: 20, pageSizes: [10, 20, 50, 100] },
  proxyConfig: {
    ajax: {
      query: async ({ page }, formValues) => {
        const res = await instanceMy({
          pageNum: page.currentPage,
          pageSize: page.pageSize,
          flowName: formValues.flowName,
          status: formValues.status,
        });
        return { items: res.data ?? [], total: res.total ?? 0 };
      },
    },
  },
  toolbarConfig: { custom: true, refresh: { code: 'query' }, search: true, zoom: true },
  formConfig: {
    enabled: true,
    items: [
      { field: 'flowName', title: '流程名称', itemRender: { name: 'Input', props: { placeholder: '流程名称' } } },
      { field: 'status', title: '状态', itemRender: { name: 'Input', props: { placeholder: '状态' } } },
    ],
  },
};

const [Grid, gridApi] = useYDSZVxeGrid({ gridOptions });
const [InstanceFormModal, instanceFormApi] = useYDSZModal({ connectedComponent: InstanceForm });

function handleAdd() { instanceFormApi.open(); }

/** 终止实例（需填写终止原因） */
async function handleTerminate(row: FlowInstanceVO) {
  if (!row.id) return;
  try {
    const { value: reason } = await ElMessageBox.prompt('请输入终止原因', '终止流程实例', {
      inputPlaceholder: 'terminate reason',
      inputValidator: (value) => (value ? true : '终止原因不能为空'),
    });
    await terminate({ id: row.id }, { reason });
    ElMessage.success('已终止');
    gridApi.query();
  } catch {
    // 用户取消或请求失败
  }
}

/** 挂起实例 */
async function handleSuspend(row: FlowInstanceVO) {
  if (!row.id) return;
  try {
    await ElMessageBox.confirm(`确定挂起流程「${row.flowName}」吗？`, '挂起确认', { type: 'warning' });
    await suspend({ id: row.id });
    ElMessage.success('已挂起');
    gridApi.query();
  } catch {
    // 用户取消或请求失败
  }
}

/** 恢复（激活）实例 */
async function handleActivate(row: FlowInstanceVO) {
  if (!row.id) return;
  try {
    await activate({ id: row.id });
    ElMessage.success('已恢复');
    gridApi.query();
  } catch {
    // 请求失败提示由拦截器统一处理
  }
}

/** 撤回实例 */
async function handleRecall(row: FlowInstanceVO) {
  if (!row.id) return;
  try {
    await ElMessageBox.confirm(`确定撤回流程「${row.flowName}」吗？`, '撤回确认', { type: 'warning' });
    await recall({ id: row.id }, {});
    ElMessage.success('已撤回');
    gridApi.query();
  } catch {
    // 用户取消或请求失败
  }
}

/** 轨迹抽屉状态 */
const timelineVisible = ref(false);
const timelineLoading = ref(false);
const timelineRows = ref<FlowTimelineVO[]>([]);

/** 查看流程运行轨迹 */
async function openTimeline(row: FlowInstanceVO) {
  if (!row.id) return;
  timelineVisible.value = true;
  timelineLoading.value = true;
  try {
    timelineRows.value = (await timeline({ id: row.id })) ?? [];
  } finally {
    timelineLoading.value = false;
  }
}
</script>
<template>
  <Page auto-content-height>
    <Grid table-title="流程实例">
      <template #toolbar-tools><ElButton type="primary" @click="handleAdd">发起流程</ElButton></template>
    </Grid>
    <InstanceFormModal @success="gridApi.query()" />
    <ElDrawer v-model="timelineVisible" title="流程运行轨迹" :size="640">
      <ElTable :data="timelineRows" border size="small" v-loading="timelineLoading">
        <ElTableColumn prop="type" label="类型" width="100" />
        <ElTableColumn prop="timestamp" label="时间" width="170" />
        <ElTableColumn prop="nodeName" label="节点" width="120" />
        <ElTableColumn prop="assigneeName" label="处理人" width="100" />
        <ElTableColumn prop="action" label="动作" width="100" />
        <ElTableColumn prop="comment" label="意见" min-width="120" show-overflow-tooltip />
        <ElTableColumn prop="taskStatus" label="任务状态" width="100" />
      </ElTable>
    </ElDrawer>
  </Page>
</template>